{"command": "python3 /work/scripts/build_pptx.py && python3 - <<'EOF'
import json, re
from pptx import Presentation
from docx import Document
import openpyxl

M = json.load(open('/work/scripts/model.json'))
def fmt(x): return f'{x:,.0f}'
KEYS = {
 'A recurring': fmt(M['A']['RECUR']), 'A net Y1': fmt(M['A']['NET_Y1']), 'A net Y2': fmt(M['A']['NET_Y2']),
 'A1 sav': fmt(M['A']['A1_SAV']), 'A2a': fmt(M['A']['A2A_SAV']), 'A2b': fmt(M['A']['A2B_SAV']),
 'A3': fmt(M['A']['A3_SAV']), 'A4': fmt(M['A']['A4_SAV']),
 'B sav': fmt(M['B']['SAV']), 'B cost': fmt(M['B']['COST_RECUR']), 'B net Y1': fmt(M['B']['NET_Y1']), 'B net Y2': fmt(M['B']['NET_Y2']),
 'B fire cut': fmt(M['B']['FIRE_CUT']), 'B nonfire cut': fmt(M['B']['NONFIRE_CUT']),
 'B backfill sal': fmt(M['backfill']['Transportation']['cost']+M['backfill']['Health Services']['cost']),
 'B backfill OT': fmt(M['B']['BACKFILL_OT_SAV']), 'B train 1x': fmt(M['B']['TRAIN_1X']), 'B train maint': fmt(M['B']['TRAIN_MAINT']),
 'B hr': fmt(M['B']['HR_COST']), 'B recruit': fmt(M['B']['RECRUIT_1X']),
 'H recur': fmt(M['H']['RECUR']), 'H fleet': fmt(M['H']['FLEET_SAV']), 'H net Y1': fmt(M['H']['NET_Y1']), 'H net Y2': fmt(M['H']['NET_Y2']),
}
scores = {'scoreA': '3.00', 'scoreB': '3.70', 'scoreH': '4.30'}

docx = '\n'.join(p.text for p in Document('/work/output/Greenfield_Decision_Briefing_Memo.docx').paragraphs)
for t in Document('/work/output/Greenfield_Decision_Briefing_Memo.docx').tables:
    for row in t.rows:
        for c in row.cells: docx += '\n' + c.text
prs = Presentation('/work/output/Greenfield_Council_Presentation.pptx')
pptx = ''
for sl in prs.slides:
    for sh in sl.shapes:
        if sh.has_text_frame: pptx += '\n' + sh.text_frame.text
        if sh.has_table:
            for row in sh.table.rows:
                for c in row.cells: pptx += '\n' + c.text
wb = openpyxl.load_workbook('/work/output/Greenfield_CostBenefit_Analysis.xlsx')
xlsx = ''
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for c in row:
            if isinstance(c.value, (int, float)): xlsx += f'\n{c.value:,.0f}'
            elif isinstance(c.value, str) and not c.value.startswith('='): xlsx += '\n' + c.value

missing = []
for k, v in KEYS.items():
    where = [name for name, txt in [('docx', docx), ('pptx', pptx), ('xlsx', xlsx)] if v in txt]
    if not where: missing.append((k, v, 'NOWHERE'))
    elif len(where) < 3 and k not in ('A3','B backfill OT','B fire cut','B nonfire cut','A2b','A4','A2a','A1 sav'):
        missing.append((k, v, 'only ' + ','.join(where)))
for k, v in scores.items():
    if v not in docx: missing.append((k, v, 'missing in docx'))
    if v not in pptx: missing.append((k, v, 'missing in pptx'))
print('INCONSISTENCIES:' if missing else 'ALL KEY FIGURES CONSISTENT')
for m in missing: print(' ', m)
print('pptx slides:', len(prs.slides.__iter__.__self__._sldIdLst))
EOF", "description": "Rebuild pptx and run cross-deliverable consistency check"}

