{"command": "cd /work/scripts && cat > more311.py << 'EOF'
import csv
from collections import defaultdict
rows = list(csv.DictReader(open('/work/task_folder/Greenfield_311_Service_Requests_FY2024.csv')))
mapdept = {'DPR':'Parks & Recreation','DSNY':'Sanitation','DOT':'Transportation','DHS':'Health Services','FDNY':'Fire Department'}
# by category
cat = defaultdict(list)
for r in rows:
    cat[(mapdept[r['Department']], r['Category'])].append(r)
res=[]
for (d,c), rs in cat.items():
    cl=[float(x['Resolution_Days']) for x in rs if x['Status']=='Closed']
    if cl:
        res.append((sum(cl)/len(cl), d, c, len(rs), len(cl), max(cl)))
res.sort(reverse=True)
print('--- top-15 slowest categories ---')
for avg,d,c,n,ncl,mx in res[:15]:
    print(f"{d} | {c}: n={n} closed={ncl} avg={avg:.1f} max={mx:.0f}")
# high priority resolution by dept
hp = defaultdict(list)
for r in rows:
    if r['Priority']=='High' and r['Status']=='Closed':
        hp[mapdept[r['Department']]].append(float(r['Resolution_Days']))
print('\n--- high-priority closed avg days ---')
for d,v in sorted(hp.items()):
    print(f"{d}: n={len(v)} avg={sum(v)/len(v):.1f}")
# open requests age proxy: days since created (no close date) -> report count + months open using date created vs 2024-06-30
from datetime import date
def dparse(s): 
    y,m,dd = s.split('-'); return date(int(y),int(m),int(dd))
anchor = date(2024,6,30)
op = defaultdict(list)
for r in rows:
    if r['Status'] in ('Open','In Progress'):
        age = (anchor - dparse(r['Date_Created'])).days
        op[mapdept[r['Department']]].append(age)
print('\n--- unresolved backlog age (days as of 6/30/2024) ---')
for d,v in sorted(op.items()):
    print(f"{d}: n={len(v)} avg_age={sum(v)/len(v):.0f} oldest={max(v)}")
# satisfaction low share
sat = defaultdict(lambda: [0,0])
for r in rows:
    if r['Satisfaction_Rating']:
        d=mapdept[r['Department']]; sat[d][0]+=int(r['Satisfaction_Rating']); sat[d][1]+=1
        if int(r['Satisfaction_Rating'])<=2: sat[d].append(1)
print('\n--- satisfaction (avg, n, %<=2) ---')
for d,(s,n) in sorted(sat.items()):
    low = len([x for x in [s] if False])
print('computed separately below')
sat2 = defaultdict(list)
for r in rows:
    if r['Satisfaction_Rating']:
